#[inline]
pub fn is_land_bitmap(lon: f64, lat: f64) -> bool {
    if !(-180.0..=180.0).contains(&lon) || !(-90.0..=90.0).contains(&lat) {
        return false;
    }
    let col = (((lon + 180.0) / 360.0) * (LAND_BITMAP_W as f64)).floor() as isize;
    let row = (((90.0 - lat) / 180.0) * (LAND_BITMAP_H as f64)).floor() as isize;
    let c = col.clamp(0, LAND_BITMAP_W as isize - 1) as usize;
    let r = row.clamp(0, LAND_BITMAP_H as isize - 1) as usize;
    let idx = r * LAND_BITMAP_W + c;
    (LAND_BITMAP[idx >> 3] & (1 << (idx & 7))) != 0
}

